/**
 * Reading back what a built page says about itself.
 *
 * The counterpart to `site-metadata.js`, which writes those tags. One place
 * decides which tags are a page naming *itself* — canonical, Open Graph and
 * the preview image — so the build check and the live check cannot drift into
 * disagreeing about what they are looking at. A page also links to a font host
 * and to sources; those are supposed to be somewhere else and are not read
 * here.
 *
 * Deliberately regex over markup rather than a parser: these pages are
 * generated by this repository, the tags are one line each, and a dependency
 * for it would be a dependency the build does not otherwise need.
 */

/** Tags by which a page claims an address of its own. */
const SELF_ADDRESSING = /rel="canonical"|og:url|og:image|twitter:image/;

/** @param {string} html */
function tagsOf(html) {
  return html.match(/<(?:link|meta)[^>]*>/g) ?? [];
}

/** @param {string} tag */
const urlIn = (tag) => tag.match(/(?:href|content)="(https?:\/\/[^"]+)"/)?.[1] ?? null;

/**
 * Every absolute address by which a page names itself, in document order.
 *
 * @param {string} html
 * @returns {string[]}
 */
export function selfDeclaredUrls(html) {
  return tagsOf(html)
    .filter((tag) => SELF_ADDRESSING.test(tag))
    .map(urlIn)
    .filter((url) => url !== null);
}

/**
 * The page's canonical address, or null if it declares none.
 *
 * @param {string} html
 * @returns {string|null}
 */
export function canonicalOf(html) {
  const tag = tagsOf(html).find((candidate) => candidate.includes('rel="canonical"'));
  return tag ? urlIn(tag) : null;
}

/**
 * An origin, or null — never a throw, so one unusable address cannot take
 * down a check that has other things to report.
 *
 * @param {unknown} url
 * @returns {string|null}
 */
export function originOf(url) {
  try {
    return new URL(String(url)).origin;
  } catch {
    return null;
  }
}
